def parse_run_line(text):
    """-> {field: value string} for the fields of FIELD_RE that the first line carries (tolerant: a missing field is simply absent)"""
    ln = first_line(text)
    out = {}
    for k, rx in FIELD_RE.items():
        m = re.search(r"(?:^|\s)" + rx + r"(?=\s|$)", ln)
        if m:
            out[k] = m.group(1)
    return out


def _same(x, y):
    if str(x).lower() == str(y).lower():
        return True
    try:
        return abs(float(x) - float(y)) <= 1e-12
    except ValueError:
        return False


def d2_line_failures(new, ref):
    """note N1 on two parsed lines: every field both carry is equal; form, replan steps, rule every, readout, kappa, model seed and reader seed are present in both; where the reference carries no pre-roll
    the new line reads `preroll 0`, no grid the new line reads `grid eval_grid_windows.json`, no nav the new line reads `nav deadreckon`. A field the reference carries and the new line lacks is not a failure of its own."""
    bad = []
    for k in D2_REQUIRED:
        if k not in new:
            bad.append("the new line carries no %s" % k)
        if k not in ref:
            bad.append("the reference line carries no %s" % k)
    for k in D2_COMPARED:
        if k in new and k in ref and not _same(new[k], ref[k]):
            bad.append("%s: new %s, reference %s" % (k, new[k], ref[k]))
    for k, dflt in D2_DEFAULTS:
        if k not in ref and not (k in new and _same(new[k], dflt)):
            bad.append("the reference line carries no %s, the new line has to read %s %s (it reads %s)" % (k, k, dflt, new.get(k)))
    return bad


# ============================================================================================ rule logs
def load_logs_setting(pull, run, m, S):
    """the rule logs of a run at setting S. Both settings use --rule-every 5, so both logs (rule_log and rule_log_mid) are needed, by the model reader's own load_logs. With no --rule-every a run writes the first
    log only; then the first log is needed and a mid log is read only if it lies on disk (kept from the reader of card ADD113)."""
    if SPEC[S]["every"] is not None:
        return MD.load_logs(pull, run, m)
    d = os.path.join(pull, "I10%s_s%d" % (run, m), "ticks")
    first = os.path.join(d, "rule_log_I10%s_s%d.npz" % (run, m))
    mid = os.path.join(d, "rule_log_mid_I10%s_s%d.npz" % (run, m))
    if not os.path.isfile(first):
        raise SystemExit("REFUSED: no rule log %s" % first)
    zs = []
    for p in [first] + ([mid] if os.path.isfile(mid) else []):
        with np.load(p, allow_pickle=False) as z:
            zs.append({k: z[k] for k in z.files})
    return zs


def rows4(logs):
    """-> (ci, j, present, g_src) over the logs of one rollout; tolerant of a log with no c_src column (the label form need not log a closing input)"""
    cols = {k: [] for k in ("ci", "j", "present", "g_src")}
    for z in logs:
        for k in cols:
            cols[k].append(np.asarray(z[k]))
    return (np.concatenate(cols["ci"]).astype(np.int64), np.concatenate(cols["j"]).astype(np.int64), np.concatenate(cols["present"]).astype(bool),
            np.concatenate(cols["g_src"]).astype(np.float64))


def gap_file_of(a, arm):
    return (getattr(a, "gap_files", None) or {}).get(NEW_FILES[arm])


def parse_gap_files(items):
    """--gap-file NAME=PATH (repeated) -> {NAME: PATH}; NAME is VGAPSP90"""
    out = {}
    for it in items or []:
        nm, sep, p = str(it).partition("=")
        if not sep or not p or nm not in NEW_FILES.values() or nm in out:
            raise SystemExit("REFUSED: --gap-file takes NAME=PATH once for each NAME of %s, got %r" % (sorted(NEW_FILES.values()), it))
        out[nm] = p
    return out


def rule_checks(a):
    """-> per-rollout dict (key S_arm_s<m>) of control p7 for the four new rollouts: the model reader's w2_one against the gap file VGAPSP90: the gap the rule received at steps with an output equals the
    file's gap within 1e-3 m; the gap the reader itself logs, for the lead steps where the file has no output, comes from the rule log of the reference run RR of the setting at the same model seed (the
    reader-fed run); the rule log meta names the hash of the gap file and the closing switch."""
    per = {}
    for S, arm in new_pairs():
        gf = gap_file_of(a, arm)
        for m in SEEDS:
            key = "%s_%s_s%d" % (S, arm, m)
            try:
                if not gf or not os.path.isfile(gf):
                    per[key] = {"PASS": False, "failures": ["no gap file %s for %s" % (gf, NEW_FILES[arm])]}
                    continue
                gref = MD.gapfile_ref(gf)
                fsha = sha_file(gf)
                logs = load_logs_setting(a.pull, run_name(S, arm), m, S)
                ref_logs = load_logs_setting(a.pull, run_name(S, "RR"), m, S)
                v0 = MD.lead_multi(MD.rows_of(ref_logs))
                meta = MD.meta_of(logs[0])
                r = MD.w2_one(MD.rows_of(logs), gref, v0, meta_expect={"vis_closing": 1}, meta=meta)
                ms = str(meta.get("vis_gap_file_sha256") or "").lower()
                if not (len(ms) >= 16 and (fsha.startswith(ms) or ms.startswith(fsha))):
                    r["failures"] = list(r.get("failures", [])) + ["rule log meta names the gap file hash %s, the file %s on disk has %s" % (ms[:16] or None, NEW_FILES[arm], fsha[:16])]
                    r["PASS"] = False
                per[key] = r
            except (SystemExit, OSError, ValueError, KeyError) as ex:
                per[key] = {"PASS": False, "failures": ["cannot read the rollout, its reference or its gap file: %s: %s" % (type(ex).__name__, ex)]}
    return per


def _hash_match(x, y):
    x, y = str(x or "").lower(), str(y or "").lower()
    return len(x) >= 16 and len(y) >= 16 and (x.startswith(y) or y.startswith(x))


def _is_hex(x, n):
    return isinstance(x, str) and len(x) == n and re.fullmatch(r"[0-9a-fA-F]+", x) is not None


def ctl_p0(rec, shas):
    """p0 gap file (card section 5), read from the record GAPSPREAD10K_GAPFILE_RECORD.json of the gap-file tool: the record names the card PREREG_V8F_PROOF_ADD134, has pass_p0 (the JSON value true),
    and files.VGAPSP90.sha256 is 64 hex characters and equals the sha256 of the gap file on disk (shas {VGAPSP90: sha256 or None})."""
    bad = []
    rec = rec if isinstance(rec, dict) else {}
    if rec.get("card") != CARD:
        bad.append("the record of the gap file names the card %r, not %s" % (rec.get("card"), CARD))
    if rec.get("pass_p0") is not True:
        bad.append("the record of the gap file has pass_p0 %s" % rec.get("pass_p0"))
    for nm in sorted(NEW_FILES.values()):
        want = ((rec.get("files") or {}).get(nm) or {}).get("sha256")
        got = (shas or {}).get(nm)
        if not _is_hex(want, 64):
            bad.append("%s: the record holds no sha256 of 64 hex characters" % nm)
        elif not got or str(got).lower() != want.lower():
            bad.append("%s on disk has sha256 %s, the record holds %s" % (nm, (got or "none")[:16], want[:16]))
    return {"pass": not bad, "failures": bad, "values": {"gap_file_sha16": {nm: str((shas or {}).get(nm) or "")[:16] for nm in sorted(NEW_FILES.values())}, "counts": rec.get("counts")}}


def ctl_wrap(wrapper_sha16, check_text, hashes_text, check_files_present, run_shas):
    """p1 wrapper (control k1 of the source): the wrapper file has the hash 28bc31f21ecb4ccb; the banked check files are in place, the pod check record ends with `ZZ CHECK-WRAPPER-V PASS` and the hashes name the wrapper; the run text of each of
    the four new runs names a wrapper hash that begins with it"""
    bad = []
    if wrapper_sha16 != WRAPPER_SHA:
        bad.append("the wrapper file is %s, not %s" % (wrapper_sha16, WRAPPER_SHA))
    if not check_files_present:
        bad.append("a banked check file of the wrapper is missing")
    if last_line(check_text).strip() != CHECK_LAST:
        bad.append("the last line of the pod check is %r" % last_line(check_text).strip())
    if WRAPPER_SHA not in (hashes_text or ""):
        bad.append("the pod check hashes do not name %s" % WRAPPER_SHA)
    for k in new_keys():
        v = run_shas.get(k)
        if v is None:
            bad.append("%s: the run text names no wrapper hash" % k)
        elif not v.startswith(WRAPPER_SHA):
            bad.append("%s: the run text names the wrapper hash %s" % (k, v[:16]))
    return {"pass": not bad, "failures": bad, "wrapper_sha16": wrapper_sha16}


