def d2_same_failures(new, ref, S, m):
    """p2 on two parsed first lines (the new run of model seed m, the banked A90 run of the same model seed): form, replan steps, rule every, readout, kappa (the heading bound), model seed and reader seed
    are present in both; every field both lines carry is equal (form, replan steps, rule every, readout, heading bound, pre-roll, exec, nav, grid, model seed, reader seed, checkpoint hash by prefix of at
    least 16 characters); a field the banked line carries and the new line lacks is a failure; the model seed of the new line is m; where the banked line carries no pre-roll, grid or nav the new line reads
    the default of the setting."""
    bad = []
    for k in D2_REQUIRED:
        if k not in new:
            bad.append("the new line carries no %s" % k)
        if k not in ref:
            bad.append("the banked line carries no %s" % k)
    if "model_seed" in new and not _same(new["model_seed"], m):
        bad.append("model seed: the new line reads %s, expected %d" % (new["model_seed"], m))
    for k in D2_COMPARED:
        if k in new and k in ref:
            same = _hash_match(new[k], ref[k]) if k == "ckpt" else _same(new[k], ref[k])
            if not same:
                bad.append("%s: new %s, banked %s" % (k, str(new[k])[:16], str(ref[k])[:16]))
        if k in ref and k not in new:
            bad.append("%s: the banked line carries it (%s), the new line does not" % (k, str(ref[k])[:16]))
    gridname = PINNED_GRID_NAME if SPEC[S]["grid_file"] == "pinned" else SPEC[S]["grid_file"]
    for k, dflt in (("preroll", str(SPEC[S]["P"])), ("grid", gridname), ("nav", "deadreckon")):
        if k not in ref and not (k in new and _same(new[k], dflt)):
            bad.append("the banked line carries no %s, the new line has to read %s %s (it reads %s)" % (k, k, dflt, new.get(k)))
    return bad


def ctl_p2(lines):
    """p2 arguments: lines {key: (text of the new run, text of the banked A90 run of the same model seed)} for the four new rollouts (d2_same_failures)"""
    bad = []
    if sorted(lines) != sorted(all_run_keys()):
        bad.append("run lines read: %d keys, expected %d" % (len(lines), len(all_run_keys())))
    spec_of = {k: (S, m) for k, nm, S, m in run_list()}
    for k, (tn, tr) in sorted(lines.items()):
        if k not in spec_of:
            continue
        S, m = spec_of[k]
        if not first_line(tn):
            bad.append("%s: no run log of the new run" % k)
            continue
        if not first_line(tr):
            bad.append("%s: no run log of the banked run" % k)
            continue
        bad += ["%s: %s" % (k, x) for x in d2_same_failures(parse_run_line(tn), parse_run_line(tr), S, m)]
    return {"pass": not bad, "failures": bad}


def _near(got, want):
    return got is not None and np.isfinite(got) and abs(float(got) - want) <= LEVEL_TOL + 1e-12


def ctl_p3(levels, pair):
    """p3 identity: the reader reproduces within 1e-4 the banked pooled levels (C, U, F) on four seeds at K0 for GEc, A90, RLc, RR (EXPECTED), read by the same code path as the new cell, and the pair
    A90 - GEc on four seeds (EXPECTED_PAIR: unsafe and falling behind, the pooled difference and the two ends of the interval). levels {S: {arm: {C,U,F}}}, pair {U: {pooled, interval}, ...}.
    The failure text names the cell and the measure and holds no value."""
    bad = []
    for S, arms in EXPECTED.items():
        for arm, want in arms.items():
            for c, v in zip("CUF", want):
                got = (((levels or {}).get(S) or {}).get(arm) or {}).get(c)
                if got is None or not np.isfinite(got):
                    bad.append("%s %s %s: no level read" % (S, arm, c))
                elif not _near(got, v):
                    bad.append("%s %s %s: not within the tolerance of the banked level" % (S, arm, c))
    for pk, ms in EXPECTED_PAIR.items():
        for mk, (pooled, lo, hi) in ms.items():
            d = ((pair or {}).get(mk) or {}) if pk == "A90-VS-GEc" else {}
            iv = d.get("interval") or [None, None]
            for lab, got, want in (("pooled difference", d.get("pooled"), pooled), ("interval low end", iv[0], lo), ("interval high end", iv[1], hi)):
                if got is None or not np.isfinite(got):
                    bad.append("K0 %s %s %s: not read" % (pk, mk, lab))
                elif not _near(got, want):
                    bad.append("K0 %s %s %s: not within the tolerance of the banked value" % (pk, mk, lab))
    return {"pass": not bad, "failures": bad}


def _pytest_ok(text, nm):
    bad = []
    hits = re.findall(r"(\d+) passed", text or "")
    if not (hits and int(hits[-1]) > 0):
        bad.append("%s: no line with a count of passed tests above 0" % nm)
    if re.search(r"\b\d+ (failed|errors?)\b", text or ""):
        bad.append("%s: the test output has a failed or error count" % nm)
    return bad


def _inside_kit(path):
    parts = [x for x in re.split(r"[\\/]+", str(path or "")) if x]
    return [d for d in KIT_DIRS if d in parts]


def ctl_p4(text_queue, text_read, mtime_queue, mtime_read, queue_start, controls_start, path_queue="", path_read=""):
    """p4 tests: the output of the queue kit's test (written by the lead outside the kit folders) and that of this kit's test each carry `N passed` and no failed or error count; the first is not later
    than the first start epoch of the queue, the second not later than the start of the controls stage; neither output lies inside a kit folder (kit_read, kit_queue)"""
    bad = _pytest_ok(text_queue, "queue kit") + _pytest_ok(text_read, "reader kit")
    mq, mr, qs, cs = to_epoch(mtime_queue), to_epoch(mtime_read), to_epoch(queue_start), to_epoch(controls_start)
    if mq is None or mr is None or qs is None or cs is None:
        bad.append("a time is missing (queue test %s, reader test %s, queue start %s, controls start %s)" % (mtime_queue, mtime_read, queue_start, controls_start))
    else:
        if not mq <= qs:
            bad.append("the queue kit's test output (%s) is later than the first start epoch of the queue (%s)" % (mq, qs))
        if not mr <= cs:
            bad.append("the reader kit's test output (%s) is later than the start of the controls stage (%s)" % (mr, cs))
    for lab, p in (("queue kit", path_queue), ("reader kit", path_read)):
        if _inside_kit(p):
            bad.append("%s: the test output lies inside the kit folder %s" % (lab, _inside_kit(p)[0]))
    return {"pass": not bad, "failures": bad}


def ctl_p5(per_setting):
    """p5 engine: for the setting K0 the engine's own controls of the grid read and of the strategic grid pass (as control g8 of the model reader)"""
    bad, det = [], {}
    if sorted(per_setting) != sorted(SETTINGS):
        bad.append("settings read: %s, expected %s" % (sorted(per_setting), sorted(SETTINGS)))
    for S, v in sorted(per_setting.items()):
        r = MD.ctl_g8(v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"))
        det[S] = {"grid_all_pass": v.get("grid_all_pass"), "strategic_stage_A_pass": v.get("strategic_a"), "strategic_stage_B_pass": v.get("strategic_b")}
        if not r["PASS"]:
            bad.append("%s: grid_all_pass %s, strategic stage A %s, stage B %s%s" % (S, v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"),
                                                                                    (" (" + v["strategic_reason"] + ")") if v.get("strategic_reason") else ""))
    return {"pass": not bad, "failures": bad, "per_setting": det}


def ctl_p6(done, n_dumps, expect, done_marker_text=None):
    """p6 counts: every new run (the four SP90 runs) has its done marker and 141 dump files (`expect`); the queue done marker reads `ZZ GAPSPREAD10K DONE <time> all steps done`.
    done {key: bool}, n_dumps {key: int}"""
    bad = []
    for k in all_run_keys():
        if done.get(k) is not True:
            bad.append("%s: no T1_DONE" % k)
        if n_dumps.get(k) != expect:
            bad.append("%s: %s dump files, %s expected" % (k, n_dumps.get(k), expect))
    if done_marker_text is not None and not DONE_RE.match(last_line(done_marker_text).strip()):
        bad.append("the queue done marker reads %r" % last_line(done_marker_text)[:100])
    return {"pass": not bad, "failures": bad, "values": {"dump_files": n_dumps, "expected": expect}}


def ctl_p7(per):
    """p7 rule logs: each new run against the gap file VGAPSP90 (rule_checks)"""
    bad = []
    if sorted(per) != sorted(rule_keys()):
        bad.append("rollouts read: %d keys, expected %d" % (len(per), len(rule_keys())))
    for k, v in sorted(per.items()):
        bad += ["%s: %s" % (k, x) for x in v.get("failures", [])]
        if v.get("PASS") is not True and not v.get("failures"):
            bad.append("%s: not pass" % k)
    shares = {k: {"share_of_rule_steps_with_a_lead": v.get("share_of_rule_steps_with_a_lead"), "n_rows": v.get("n_rows"), "n_lead_rows": v.get("n_lead_rows"),
                  "share_of_lead_steps_with_nonzero_closing": v.get("share_of_lead_steps_with_nonzero_closing")} for k, v in per.items()}
    return {"pass": not bad and bool(per), "failures": bad, "values": {"rollout_shares": shares}}


def dump_count(pull, nm, mm):
    dd = os.path.join(run_folder(pull, nm, mm), "dump_I10%s_s%d_m10_causal_heads" % (nm, mm))
    return len([f for f in (os.listdir(dd) if os.path.isdir(dd) else []) if f.startswith("ep") and f.endswith(".npz")])


def compute_controls(a, m, wsha):
    """the eight controls p0 to p7 from the files on disk and the engine measures `m` ({"settings": {S: {levels, pairs, grid_all_pass, strategic_a, strategic_b}}}).
    p0: the record of the gap file; p1: the wrapper; p2: the first line of each new run against that of the banked A90 run of the same model seed; p3: identity of the banked levels and of the pair A90 - GEc;
    p4: tests; p5: engine; p6: counts; p7: rule logs."""
    c = {}
    gf = getattr(a, "gap_files", None) or {}
    shas = {nm: (sha_file(p) if p and os.path.isfile(p) else None) for nm, p in gf.items()}
    c["p0"] = ctl_p0(read_json(a.gap_record), shas)
    rshas = {"%s_%s_s%d" % (S, arm, mm): MD.run_file_sha(a.pull, run_name(S, arm), mm) for S, arm in new_pairs() for mm in SEEDS}
    present = bool(a.wrapper_check and os.path.isfile(a.wrapper_check) and a.wrapper_hashes and os.path.isfile(a.wrapper_hashes))
    c["p1"] = ctl_wrap(wsha, read_text(a.wrapper_check), read_text(a.wrapper_hashes), present, rshas)
    lines = {k: (read_text(run_text_path(a.pull, nm, mm)), read_text(run_text_path(a.pull, run_name(S, ref_arm(S, "SP90")), mm))) for k, nm, S, mm in run_list()}
    c["p2"] = ctl_p2(lines)
    sets = m.get("settings") or {}
    k0 = sets.get("K0") or {}
    c["p3"] = ctl_p3({S: (v or {}).get("levels") for S, v in sets.items()}, (k0.get("pairs") or {}).get("A90-VS-GEc"))
    c["p4"] = ctl_p4(read_text(a.tests_queue), read_text(a.tests_read), a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start, a.tests_queue, a.tests_read)
    c["p5"] = ctl_p5(sets)
    done, n_dumps = {}, {}
    for k, nm, S, mm in run_list():
        done[k] = os.path.isfile(os.path.join(run_folder(a.pull, nm, mm), "T1_DONE"))
        n_dumps[k] = dump_count(a.pull, nm, mm)
    c["p6"] = ctl_p6(done, n_dumps, int(getattr(a, "expect_dumps", EXPECT_DUMPS)), read_text(a.done_marker) if getattr(a, "done_marker", "") else None)
    c["p7"] = ctl_p7(rule_checks(a))
    return c


def assemble_controls(controls, payload, inputs):
    ok = sorted(controls) == sorted(CONTROLS) and all(isinstance(v, dict) and v.get("pass") is True for v in controls.values())
    vals = {k: v["values"] for k, v in controls.items() if isinstance(v, dict) and "values" in v}
    flat = {k: ({kk: vv for kk, vv in v.items() if kk != "values"} if isinstance(v, dict) else v) for k, v in controls.items()}
    pl = dict(payload)
    pl["control_values"] = vals
    res = {"card": CARD, "tier": TIER, "controls": flat, "all_pass": ok, "inputs": inputs}
    res["payload" if ok else "withheld"] = pl
    return res


# ============================================================================================ names (two separate derivations)
def _sg(iv):
    return -1 if iv[1] < 0.0 else (1 if iv[0] > 0.0 else 0)


def names_of(payload):
    """card section 4, written from the interval ends. For each pair P of NAMED and measure M: `GAPSPREAD10K-K0-<P>-LOWERS-<M>` (interval below 0), `-RAISES-<M>` (above 0), `-<M>-NOT-SEPARATED`.
    One overall name from SP90 - A90, the first clause that holds: 1 PLACED-GIVES-UP-SAFETY (the unsafe or the contact interval above 0); 2 PLACED-SAME-SAFETY-AT-A-LOWER-PRICE (the upper end of the
    unsafe interval at most HALF_BOUND, the contact interval not above 0, the falling-behind interval below 0); 3 PLACED-SAFER-AT-NO-HIGHER-PRICE (the unsafe interval below 0 and the falling-behind
    interval not above 0); 4 PLACED-NOT-SEPARATED-FROM-FLAT."""
    out = {}
    pr = payload["settings"]["K0"]["pairs"]
    for P, pk in NAMED:
        for mk, mw in MEASURES:
            iv = pr[pk][mk]["interval"]
            if iv[1] < 0.0:
                out["%s_%s" % (P, mw)] = "%s-K0-%s-LOWERS-%s" % (PRE, P, mw)
            elif iv[0] > 0.0:
                out["%s_%s" % (P, mw)] = "%s-K0-%s-RAISES-%s" % (PRE, P, mw)
            else:
                out["%s_%s" % (P, mw)] = "%s-K0-%s-%s-NOT-SEPARATED" % (PRE, P, mw)
    u, c, f = (pr["SP90-VS-A90"][mk]["interval"] for mk in "UCF")
    if u[0] > 0.0 or c[0] > 0.0:
        tail = "PLACED-GIVES-UP-SAFETY"
    elif u[1] <= HALF_BOUND and not c[0] > 0.0 and f[1] < 0.0:
        tail = "PLACED-SAME-SAFETY-AT-A-LOWER-PRICE"
    elif u[1] < 0.0 and not f[0] > 0.0:
        tail = "PLACED-SAFER-AT-NO-HIGHER-PRICE"
    else:
        tail = "PLACED-NOT-SEPARATED-FROM-FLAT"
    out["OVERALL"] = "%s-K0-%s" % (PRE, tail)
    return out


def derive_all(payload):
    """independent second derivation of every name from the signs of the interval ends (written apart from names_of, with the words written out)"""
    d = payload["settings"]["K0"]["pairs"]
    out = {}
    sgn = {}
    verb = {-1: "-LOWERS-", 1: "-RAISES-"}
    for P, pk in (("VS-FLAT", "SP90-VS-A90"), ("VS-CANDIDATE", "SP90-VS-GEc")):
        for mk, mw in (("U", "UNSAFE"), ("C", "CONTACT"), ("F", "FALLING-BEHIND")):
            lo, hi = d[pk][mk]["interval"]
            s = _sg([lo, hi])
            sgn[(P, mk)] = s
            out["%s_%s" % (P, mw)] = "GAPSPREAD10K-K0-" + P + ((verb[s] + mw) if s else ("-" + mw + "-NOT-SEPARATED"))
    sU, sC, sF = sgn[("VS-FLAT", "U")], sgn[("VS-FLAT", "C")], sgn[("VS-FLAT", "F")]
    u_hi = d["SP90-VS-A90"]["U"]["interval"][1]
    if sU == 1 or sC == 1:
        tail = "PLACED-GIVES-UP-SAFETY"
    elif u_hi <= 0.0058 and sF == -1:
        tail = "PLACED-SAME-SAFETY-AT-A-LOWER-PRICE"
    elif sU == -1 and sF != 1:
        tail = "PLACED-SAFER-AT-NO-HIGHER-PRICE"
    else:
        tail = "PLACED-NOT-SEPARATED-FROM-FLAT"
    out["OVERALL"] = "GAPSPREAD10K-K0-" + tail
    return out


def all_names(payload):
    got = names_of(payload)
    exp = derive_all(payload)
    diff = ["%s: got %s, expected %s" % (k, got.get(k), v) for k, v in sorted(exp.items()) if got.get(k) != v]
    diff += ["%s: name present that the card does not have" % k for k in sorted(got) if k not in exp]
    if diff:
        raise SystemExit("REFUSED: the names are not the ones the intervals give: %s" % diff)
    return got


def flat_names(names):
    return [names[k] for k in sorted(names)]


# ============================================================================================ the pod part (grid read and strategic read per setting)
def register_runs(S):
    spec = SPEC[S]
    for arm, r in spec["runs"].items():
        R.ALL_RUNS.setdefault(r, ("RLc" if arm == "RLc" else "RR", spec["readout"], spec["P"], "deadreckon", spec["grid"], "plan", spec["every"], 0.2))
    R.ALL_RUNS.setdefault(SPREAD, ("R0", "pinned", 0, "deadreckon", "full", "plan", None, 0.2))


class SeedsCtx(object):
    """sets the module global SEEDS of the engine's grid reader (read_longroll10k) and, when it is loaded, that of the strategic reader (strat_roll_read) for one read, then restores both"""

    def __init__(self, seeds):
        self.seeds = tuple(seeds)
        self.old = []

    def __enter__(self):
        mods = [R]
        try:
            import importlib
            mods.append(importlib.import_module("strat_roll_read"))
        except ImportError:
            pass
        for md in mods:
            self.old.append((md, md.SEEDS))
            md.SEEDS = self.seeds
        return self

    def __exit__(self, *exc):
        for md, v in self.old:
            md.SEEDS = v
        return False


class R0Alias(object):
    """the strategic grid compares every run with the unscaled reference run R0 at the same model seed; the card queues the spread run R0Hb20 at the new seeds and no run called R0, so for a model seed
    of 2 or more the tick file of R0 is that of R0Hb20 (the heading bound 0.2 of the card's own runs; the control s5 only compares first ticks). Open decision, written in REPL_READ_DEFS.md."""

    def __enter__(self):
        import importlib
        self.S = importlib.import_module("strat_roll_read")
        self.orig = self.S.tick_path
        orig = self.orig

        def tp(W, run, k):
            return orig(W, SPREAD if (run == "R0" and k >= 2) else run, k)
        self.S.tick_path = tp
        return self

    def __exit__(self, *exc):
        self.S.tick_path = self.orig
        return False


def read_all(a, E, S, keys, log):
    """one grid read of the five arms of the setting over the four model seeds (levels per seed and pooled, pairs with intervals, families), engine calls as in the model reader"""
    spec = SPEC[S]
    runs = spec["runs"]
    pairs_def = {nm: (runs[x], runs[y]) for nm, (x, y) in PAIRS.items()}
    with SeedsCtx(SEEDS):
        G = R.read_grid(a, E, spec["grid"], keys, [SPREAD] + sorted(set(runs.values())), SPREAD, pairs_def, {}, log)
    out = {"seeds": list(SEEDS), "grid_all_pass": G["controls"].get("ALL_PASS") is True, "counts": G.get("counts") or {}, "levels": {}, "levels_per_seed": {}, "pairs": {}, "families": {}}
    if all(r in (G.get("levels") or {}) for r in runs.values()):
        out["levels"] = {arm: {c: float(np.mean(G["levels"][r][c])) for c in ("C", "U", "F")} for arm, r in runs.items()}
        out["levels_per_seed"] = {arm: {c: [float(v) for v in np.asarray(G["levels"][r][c]).reshape(-1)] for c in ("C", "U", "F")} for arm, r in runs.items()}
    if G.get("pairs"):
        out["pairs"] = {nm: R.ucf(p["headway"]) for nm, p in G["pairs"].items()}
        out["families"] = {nm: {f_: R.reading(R.cells_of(p["family"]), f_) for f_ in R.NAMED} for nm, p in G["pairs"].items()}
    return out


def strat_setting(a, S, keys, ctx_cache, log, out):
    """the strategic grid of one setting at T1-kin: cells of all four model seeds in one pass, the pair reads over the four seeds for SP90 - A90 and SP90 - GEc"""
    runs = SPEC[S]["runs"]
    p_of = {"R0": 0}
    p_of.update({r: SPEC[S]["P"] for r in runs.values()})
    try:
        with SeedsCtx(SEEDS), R0Alias():
            SR, cells_s, eid_s, SS = R.strategic_grid(a, keys, sorted(p_of), p_of, log, ctx_cache)
    except SystemExit as ex:
        out["strategic_reason"] = "SystemExit: %s" % str(ex)[:200]
        return
    except Exception as ex:                                                                   # noqa: BLE001
        out["strategic_reason"] = "%s: %s" % (type(ex).__name__, str(ex)[:200])
        return
    sa, sb = bool(SR.get("stage_A_pass")), bool(SR.get("stage_B_pass"))
    out["strategic_a"], out["strategic_b"] = sa, sb
    out["strategic"]["controls"] = dict({k: v for k, v in SR["controls"].items() if k != "s3"}, s3=SR["controls"]["s3"].get("pass"))
    if sa and sb:
        with SeedsCtx(SEEDS):
            for nm, (x, y) in STRAT_PAIRS.items():
                pr = SS.pair_read(cells_s, runs[x], runs[y], eid_s, ticks=(2,))
                pos = pr["tick2"]["pos"]
                out["strategic"]["pairs"][nm] = {"A": runs[x], "B": runs[y], "pos_30_50_80m_tick_t0_plus_20": [
                    {"arc_m": arc, "mean": b["mean"], "lo": b["lo"], "hi": b["hi"], "verdict": b["verdict"], "n_per_seed": b.get("n_per_seed")} for arc, b in zip(SS.ARCS, pos)],
                    "reading": R.family_of([c["verdict"] for c in pos])}
    else:
        out["strategic_reason"] = "the engine's strategic controls did not pass"


def measure_setting(a, E, S, keys, ctx_cache, log):
    """the grid read of one setting over the four model seeds and the strategic grid"""
    H = E[0]
    register_runs(S)
    rd = read_all(a, E, S, keys, log)
    out = {"grid_all_pass": rd["grid_all_pass"], "counts": rd["counts"], "levels": rd["levels"], "levels_per_seed": rd["levels_per_seed"], "pairs": rd["pairs"], "families": rd["families"],
           "strategic": {"pairs": {}}, "strategic_a": False, "strategic_b": False}
    if out["counts"]:
        out["instrument_bar_met"] = bool(out["counts"].get("n_lead_windows", 0) >= H.MIN_WINDOWS and out["counts"].get("n_episodes_with_lead", 0) >= H.MIN_EPISODES)
    strat_setting(a, S, keys, ctx_cache, log, out)
    return out


def grid_path(a, S):
    gf = SPEC[S]["grid_file"]
    return a.grid_pinned if gf == "pinned" else os.path.join(a.grid_dir, gf)


def measure(a, E, log):
    H = E[0]
    J = H.load_join()
    names_ = [str(c) for c in J["clip"]]
    ctx_cache = {}
    res = {}
    for S in SETTINGS:
        g = R.jl(grid_path(a, S))
        if g is None:
            res[S] = {"grid_all_pass": False, "levels": {}, "pairs": {}, "strategic_a": False, "strategic_b": False, "strategic_reason": "grid file %s cannot be read" % grid_path(a, S)}
            continue
        keys = R.grid_keys(g, names_)
        res[S] = measure_setting(a, E, S, keys, ctx_cache, log)
    return {"settings": res}


def input_files(a):
    """the files the controls stage reads, with their paths and sha256 (None for a file that is not there): the names stage hashes them again and refuses when one differs"""
    items = [("this_reader", os.path.abspath(__file__)), ("model_reader", MODEL_PATH), ("wrapper_file", getattr(a, "wrapper_file", "")), ("wrapper_check", getattr(a, "wrapper_check", "")),
             ("wrapper_hashes", getattr(a, "wrapper_hashes", "")), ("gap_record", a.gap_record), ("grid_pinned", getattr(a, "grid_pinned", "")), ("tests_queue", getattr(a, "tests_queue", "")),
             ("tests_read", getattr(a, "tests_read", "")), ("done_marker", getattr(a, "done_marker", ""))]
    items += [(nm, (getattr(a, "gap_files", None) or {}).get(nm)) for nm in sorted(NEW_FILES.values())]
    items += [("run_text_" + k, run_text_path(a.pull, nm, mm)) for k, nm, S, mm in run_list()]
    return {lab: {"path": os.path.abspath(p), "sha256": sha_file(p) if os.path.isfile(p) else None} for lab, p in items if p}


def inputs_changed(inputs):
    """-> the list of differences between the hashes the controls stage recorded and the files now; a record with no file hashes is a difference"""
    fl = (inputs or {}).get("files") if isinstance(inputs, dict) else None
    if not isinstance(fl, dict) or not fl:
        return ["the controls file records no input hashes"]
    bad = []
    for lab, v in sorted(fl.items()):
        p, want = (v or {}).get("path"), (v or {}).get("sha256")
        got = sha_file(p) if p and os.path.isfile(p) else None
        if got != want:
            bad.append("%s: sha256 %s now, %s at the controls stage" % (lab, (got or "none")[:16], (want or "none")[:16]))
    return bad


def run_controls(a):
    elog = a.out + ".engine.log"
    if os.path.exists(elog):
        raise SystemExit("REFUSED: %s exists" % elog)
    with io.open(elog, "w", encoding="utf-8", newline="\n") as fh, contextlib.redirect_stdout(fh):
        E = R.engine(a)
        m = measure(a, E, lambda s: print(s, flush=True))
    wsha = sha_file(a.wrapper_file)[:16] if a.wrapper_file and os.path.isfile(a.wrapper_file) else None
    controls = compute_controls(a, m, wsha)
    payload = {"settings": m["settings"], "family_note": FAM_NOTE}
    inputs = {"files": input_files(a), "wrapper_file_sha16": wsha}
    return assemble_controls(controls, payload, inputs)


def one_line(x, n=160):
    return " ".join(str(x).split())[:n]


def controls_lines(res):
    """the lines of the controls stage: `ctl p<k> PASS` or `ctl p<k> FAIL <first reason>` and the last line. No level, no difference and no name."""
    L = []
    for k in CONTROLS:
        c = (res.get("controls") or {}).get(k) or {}
        if c.get("pass") is True:
            L.append("ctl %s PASS" % k)
        else:
            L.append("ctl %s FAIL %s" % (k, one_line((c.get("failures") or ["not computed"])[0])))
    L.append("ZZ READ-GAPSPREAD10K controls all_pass %s" % res.get("all_pass"))
    return L


def fmt_pair(p):
    return "; ".join("%s %s" % (label, json.dumps(p[mk], sort_keys=True, default=str)) for mk, label in MEASURES)


def print_sections(payload, names):
    L = ["TIER " + TIER]
    L += flat_names(names)
    d = payload["settings"]["K0"]
    cn = d.get("counts") or {}
    L.append("setting K0 (%s; grid %s): windows %s, windows with a lead %s, episodes with a lead %s, instrument bar of 200 windows and 20 episodes met %s" % (
        preroll_text(SPEC["K0"]["P"]), SPEC["K0"]["grid"], cn.get("n_windows"), cn.get("n_lead_windows"), cn.get("n_episodes_with_lead"), d.get("instrument_bar_met")))
    for arm in ARMS:
        lv = d["levels"][arm]
        L.append("level K0 %s pooled over four model seeds C %.4f U %.4f F %.4f; per model seed 0 to 3 %s" % (arm, lv["C"], lv["U"], lv["F"], json.dumps((d.get("levels_per_seed") or {}).get(arm), sort_keys=True)))
    for nm in PAIRS:
        L.append("K0 %s (%s): %s" % (nm, "named" if nm in dict((pk, P) for P, pk in NAMED) else "no name", fmt_pair(d["pairs"][nm])))
    for nm in STRAT_PAIRS:
        st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
        L.append("families K0 %s: %s strategic %s" % (nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True), st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
    cv = payload.get("control_values") or {}
    sh = (cv.get("p7") or {}).get("rollout_shares") or {}
    for k in sorted(sh):
        L.append("rollout %s: %s" % (k, json.dumps(sh[k], sort_keys=True)))
    return L


LIMITS = ("T1-kin only, no re-perception: the lead moves as logged whatever the ego does; readout K with no pre-roll alone (the margin is a setting of readout K); four model seeds of one line, two pairs of training runs; "
          "one dose, one floor; the hypothesis was formed after the data of row 201 and the form of SP90 was fixed before it; the label form is a reference with label values and not a candidate.")


def verdict_md(payload, names, controls_sha):
    """GAPSPREAD10K_VERDICT.md: tier, controls, names, levels pooled and per model seed, pairs with intervals, the four families, the limits of card section 7"""
    L = ["# GAPSPREAD10K verdict (card %s)" % CARD, "",
         "Tier: %s. A kinematic rollout on recorded frames, on the model's own actions; not driving performance." % TIER, "",
         "Controls: p0 to p7 all pass (controls file sha256 %s). This card has no map of arms to controls." % controls_sha[:16], "",
         "Estimator: two-level bootstrap over the four model seeds and the evaluation episodes, 2,000 draws, on the same windows for both arms of a pair. The interval answers what another draw of "
         "episodes and of these four model seeds would say, not what another training run would say; the four seeds are two pairs of training runs of one line.", "", "## Names", ""]
    L += ["- " + n for n in flat_names(names)]
    d = payload["settings"]["K0"]
    cn = d.get("counts") or {}
    L += ["", "## Setting K0 (%s)" % preroll_text(SPEC["K0"]["P"]), "", "Windows with a lead %s, episodes with a lead %s." % (cn.get("n_lead_windows"), cn.get("n_episodes_with_lead")), "",
          "### Levels (contact C, unsafe U, falling behind F)", ""]
    for arm in ARMS:
        lv = d["levels"][arm]
        L.append("- %s pooled over four model seeds C %.4f U %.4f F %.4f; per model seed %s" % (arm, lv["C"], lv["U"], lv["F"], json.dumps((d.get("levels_per_seed") or {}).get(arm), sort_keys=True)))
    L += ["", "### Pairs (first minus second, with intervals)", ""]
    for nm in PAIRS:
        L.append("- %s: %s" % (nm, fmt_pair(d["pairs"][nm])))
    L += ["", "### Families (longitudinal, lateral, tactical: engine reads of each pair; strategic: grid at T1-kin, position error at 30, 50 and 80 m)", ""]
    for nm in STRAT_PAIRS:
        st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
        L.append("- %s: %s; strategic %s" % (nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True), st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
    L += ["", "## Limits (card section 7)", "", LIMITS, "", "This card has no map of arms to controls.", ""]
    return "\n".join(L)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    ap = argparse.ArgumentParser(allow_abbrev=False)
    ap.add_argument("--stage", choices=("controls", "names"))
    ap.add_argument("--selftest", action="store_true")
    for nme in ("pull", "code", "grid-dir", "grid-pinned", "w", "tree", "wrapper-file", "wrapper-check", "wrapper-hashes", "controls", "gap-record", "verdict",
                "eval-join", "tests-queue", "tests-read", "tests-mtime-queue", "tests-mtime-read", "queue-start", "controls-start", "done-marker", "model-reader"):
        ap.add_argument("--" + nme, default="")
    ap.add_argument("--gap-file", action="append", default=[])
    ap.add_argument("--out", default="")
    ap.add_argument("--log", default="")
    ap.add_argument("--n-boot", type=int, default=2000)
    ap.add_argument("--expect-dumps", type=int, default=EXPECT_DUMPS)
    a = ap.parse_args(argv)
    if a.selftest:
        print("REFUSED: this reader has no selftest; its tests are in test_gapspread_read.py")
        return 2
    if not a.stage or not a.out:
        print("REFUSED: --stage and --out are required")
        return 2
    bind(a.model_reader)
    a.n_boot_control = 300
    if os.path.exists(a.out):
        print("REFUSED: %s exists" % a.out)
        return 2
    if a.stage == "controls":
        a.gap_record = a.gap_record or WS + "/gapspread10k/gapfiles/GAPSPREAD10K_GAPFILE_RECORD.json"
        a.gap_files = parse_gap_files(a.gap_file)
        for nm in sorted(NEW_FILES.values()):
            a.gap_files.setdefault(nm, WS + "/gapspread10k/gapfiles/%s.npz" % nm)
        a.grid_pinned = a.grid_pinned or WS + "/hierrep/pins/" + PINNED_GRID_NAME
        a.tests_queue = a.tests_queue or WS + "/gapspread10k/lead_tests/lead_pytest_queue.out"
        a.tests_read = a.tests_read or WS + "/gapspread10k/lead_tests/lead_pytest_read.out"
        res = run_controls(a)
        io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1, default=lambda o: float(o) if hasattr(o, "item") else str(o)))
        for ln in controls_lines(res):
            print(ln)
        return 0
    cj = read_json(a.controls) or {}
    if cj.get("card") != CARD or cj.get("all_pass") is not True or "payload" not in cj or sorted(cj.get("controls", {})) != sorted(CONTROLS) \
            or any((v or {}).get("pass") is not True for v in cj.get("controls", {}).values()):
        print("REFUSED: the controls file is not all-pass with p0 to p7 present: no name is written")
        print("ZZ READ-GAPSPREAD10K names refused")
        return 3
    diff = inputs_changed(cj.get("inputs"))
    if diff:
        print("REFUSED: an input is not as the controls stage hashed it: %s" % one_line("; ".join(diff), 400))
        print("ZZ READ-GAPSPREAD10K names refused")
        return 3
    logp = a.log or (os.path.splitext(a.out)[0] + "_names.log")
    vp = a.verdict or os.path.join(os.path.dirname(os.path.abspath(a.out)), PRE + "_VERDICT.md")
    for p in (logp, vp):
        if os.path.exists(p):
            print("REFUSED: %s exists" % p)
            return 2
    names = all_names(cj["payload"])
    csha = sha_file(a.controls)
    res = {"card": CARD, "tier": TIER, "controls_file": os.path.abspath(a.controls), "controls_sha256": csha, "names": names, "values": cj["payload"]}
    io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1))
    io.open(vp, "w", encoding="utf-8", newline="\n").write(verdict_md(cj["payload"], names, csha))
    lines = print_sections(cj["payload"], names) + ["ZZ READ-GAPSPREAD10K names done"]
    io.open(logp, "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    for ln in lines:
        print(ln)
    return 0


try:
    bind(os.environ.get("GAPSPREAD_MODEL_READER", ""))
except ImportError as _ex:                      # bound again in main() from --model-reader; a missing one is reported there
    print("NOTE: %s" % _ex, file=sys.stderr)

if __name__ == "__main__":
    sys.exit(main())
